    if types and not set(types) & INVESTING_TYPES:
        code = next(NON_INVESTOR_TYPES[t] for t in NON_INVESTOR_TYPES if t in types) if set(types) & set(NON_INVESTOR_TYPES) else "E7"
        return out("REJECTED", code, f"evidence shows type {types}, not an investor into companies")
