from pathlib import Path

root = Path(sys_argv := __import__("sys").argv[1])
dec = {r["candidate_id"]: r for r in csv.DictReader(open(root / "data/processed/decisions.csv", encoding="utf-8"))}
claims = list(csv.DictReader(open(root / "data/processed/claims.csv", encoding="utf-8")))
key = {r["review_id"]: r for r in csv.DictReader(open(root / "data/review/review_key.csv", encoding="utf-8"))}
sonnet = {}
for p in sorted((root / "data/review/sonnet").glob("s_b*.json")):
    for r in json.loads(p.read_text(encoding="utf-8")):
        sonnet[key[r["review_id"]]["candidate_id"]] = r.get("identity_ok") or {}

for cid, d in dec.items():
    if d["status"] not in ("INCLUDED",) and cid not in sonnet:
        continue
    ids = [json.loads(c["value"]) for c in claims if c["candidate_id"] == cid and c["field"] == "identity" and c["auto_check"] == "ok"]
    path = "ico_claim" if any(v.get("company_id") for v in ids) else "legal_name" if ids else "brand/triage"
    s = sonnet.get(cid, {})
    print(f"{cid} {d['name'][:24]:<24} {d['status'][:8]:<8} {path:<12} -> {d['legal_name'][:45]:<45} {d['company_id']:<9} "
          f"| sonnet: {s.get('answer', '-'):<11} {s.get('why', '')[:90]}")

